/* ------------------------------- insights view ------------------------------- */

function InsightsView({ products, logs, photoIndex = {}, photoCache = {}, loadPhoto, quotaUsedMB = 0, quotaPct = 0, onExport }) {
  const dates = Object.keys(logs).sort();
  const hasAnyLogs = dates.length > 0;
  const todayD = todayStr();
  const thisMonth = monthKey(todayD);
  const [lightbox, setLightbox] = useState(null);
  const [showExport, setShowExport] = useState(false);
  const [historyProduct, setHistoryProduct] = useState(null);

  const firstDate = dates[0] || todayD;
  const rangeDays = useMemo(() => {
    if (!hasAnyLogs) return [];
    const out = [];
    for (let c = firstDate; c <= todayD; c = addDays(c, 1)) out.push(c);
    return out;
  }, [firstDate, todayD, hasAnyLogs]);

  const photoEntries = useMemo(() => {
    const list = [];
    Object.keys(photoIndex).forEach((d) => {
      const slot = photoIndex[d];
      (slot.am || []).forEach((id) => list.push({ date: d, period: "am", id }));
      (slot.pm || []).forEach((id) => list.push({ date: d, period: "pm", id }));
    });
    return list.sort((a, b) => (a.date === b.date ? (a.period < b.period ? -1 : 1) : a.date < b.date ? -1 : 1));
  }, [photoIndex]);

  // ---- empty state ----
  if (!hasAnyLogs) {
    return (
      <div style={{ padding: "24px 20px 8px" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
          <BarChart3 size={16} style={{ color: "var(--amber)" }} />
          <span className="font-mono" style={{ fontSize: 11, letterSpacing: 2, color: "var(--muted)" }}>INSIGHTS</span>
        </div>
        <h2 className="font-display" style={{ fontSize: 26, color: "var(--mist)", margin: "4px 0 30px", fontWeight: 500 }}>What the data says</h2>
        <div style={{ textAlign: "center", marginTop: 30 }}>
          <Sparkles size={24} style={{ color: "var(--muted)", marginBottom: 12 }} />
          <div style={{ fontSize: 13.5, color: "var(--mist)", marginBottom: 4 }}>Nothing to show yet</div>
          <div style={{ fontSize: 12, color: "var(--muted)", maxWidth: 220, margin: "0 auto" }}>
            Check off a few days on Today and your patterns will start showing up here.
          </div>
        </div>
      </div>
    );
  }

  // ---- monthly consistency (current) ----
  const monthDates = dates.filter((d) => monthKey(d) === thisMonth);
  const dayOfMonth = parseDate(todayD).getDate();
  const completeDaysThisMonth = monthDates.filter((d) => anyChecked(logs[d].am) && anyChecked(logs[d].pm)).length;
  const consistency = dayOfMonth ? Math.round((completeDaysThisMonth / dayOfMonth) * 100) : 0;

  // ---- longest streak ever + current streak ----
  let longest = 0, run = 0;
  rangeDays.forEach((d) => {
    const l = logs[d];
    const complete = l && anyChecked(l.am) && anyChecked(l.pm);
    if (complete) { run++; longest = Math.max(longest, run); } else { run = 0; }
  });
  let currentStreak = 0, cur = todayD;
  while (true) {
    const l = logs[cur];
    if (l && anyChecked(l.am) && anyChecked(l.pm)) { currentStreak++; cur = addDays(cur, -1); } else break;
  }

  // ---- journey summary: totals + biggest gap ever ----
  let totalCheckins = 0;
  dates.forEach((d) => {
    const l = logs[d];
    totalCheckins += Object.values(l.am || {}).filter(Boolean).length + Object.values(l.pm || {}).filter(Boolean).length;
  });
  let biggestGap = 0, gapRun = 0;
  rangeDays.forEach((d) => {
    const l = logs[d];
    const missed = !(l && (anyChecked(l.am) || anyChecked(l.pm)));
    if (missed) { gapRun++; biggestGap = Math.max(biggestGap, gapRun); } else { gapRun = 0; }
  });

  // ---- partial-day credit breakdown, this month ----
  let fullDays = 0, partialDays = 0, missedDays = 0;
  const monthRangeSoFar = [];
  for (let c = thisMonth + "-01"; c <= todayD; c = addDays(c, 1)) monthRangeSoFar.push(c);
  monthRangeSoFar.forEach((d) => {
    const l = logs[d];
    const hasAm = l && anyChecked(l.am);
    const hasPm = l && anyChecked(l.pm);
    if (hasAm && hasPm) fullDays++;
    else if (hasAm || hasPm) partialDays++;
    else missedDays++;
  });
  const monthTotalDays = fullDays + partialDays + missedDays;

  // ---- mood distribution this month ----
  const moodCounts = {};
  MOODS.forEach((m) => (moodCounts[m] = 0));
  monthDates.forEach((d) => {
    const l = logs[d];
    [l.amMood, l.pmMood].forEach((m) => { if (m && moodCounts[m] !== undefined) moodCounts[m]++; });
  });
  const maxMoodCount = Math.max(1, ...Object.values(moodCounts));
  const totalMoodLogs = Object.values(moodCounts).reduce((a, b) => a + b, 0);

  // ---- 6-month consistency trend ----
  const monthTrend = [];
  for (let i = 5; i >= 0; i--) {
    const base = new Date();
    base.setDate(1);
    base.setMonth(base.getMonth() - i);
    const mk = monthKey(fmtDate(base));
    const daysCounted = mk === thisMonth ? dayOfMonth : new Date(base.getFullYear(), base.getMonth() + 1, 0).getDate();
    const mDates = dates.filter((d) => monthKey(d) === mk);
    const complete = mDates.filter((d) => anyChecked(logs[d].am) && anyChecked(logs[d].pm)).length;
    const pct = daysCounted ? Math.round((complete / daysCounted) * 100) : 0;
    monthTrend.push({ label: base.toLocaleDateString(undefined, { month: "short" }), pct, isCurrent: mk === thisMonth, hasData: mDates.length > 0 });
  }
  const prevMonthEntry = monthTrend[4];
  const monthDelta = prevMonthEntry && prevMonthEntry.hasData ? consistency - prevMonthEntry.pct : null;

  // ---- AM vs PM split ----
  const amDays = dates.filter((d) => anyChecked(logs[d].am)).length;
  const pmDays = dates.filter((d) => anyChecked(logs[d].pm)).length;
  const amPct = Math.round((amDays / dates.length) * 100);
  const pmPct = Math.round((pmDays / dates.length) * 100);

  // ---- skip-day pattern by weekday (worst + best) ----
  const weekdayNames = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
  const missByWeekday = [0, 0, 0, 0, 0, 0, 0];
  const fullByWeekday = [0, 0, 0, 0, 0, 0, 0];
  const totalByWeekday = [0, 0, 0, 0, 0, 0, 0];
  rangeDays.forEach((d) => {
    const wd = parseDate(d).getDay();
    totalByWeekday[wd]++;
    const l = logs[d];
    if (!(l && (anyChecked(l.am) || anyChecked(l.pm)))) missByWeekday[wd]++;
    if (l && anyChecked(l.am) && anyChecked(l.pm)) fullByWeekday[wd]++;
  });
  let worstIdx = -1, worstRate = 0;
  missByWeekday.forEach((m, i) => {
    if (totalByWeekday[i] >= 2 && m > 0) {
      const rate = m / totalByWeekday[i];
      if (rate > worstRate) { worstRate = rate; worstIdx = i; }
    }
  });
  let bestIdx = -1, bestRate = 0;
  fullByWeekday.forEach((c, i) => {
    if (totalByWeekday[i] >= 2) {
      const rate = c / totalByWeekday[i];
      if (rate > bestRate) { bestRate = rate; bestIdx = i; }
    }
  });
  const skipPattern = rangeDays.length >= 14 && worstIdx >= 0 && worstRate >= 0.4
    ? `You miss ${weekdayNames[worstIdx]}s most often`
    : null;
  const bestDayPattern = rangeDays.length >= 14 && bestIdx >= 0 && bestRate >= 0.5 && bestIdx !== worstIdx
    ? `You're most consistent on ${weekdayNames[bestIdx]}s`
    : null;

  // ---- cautious correlation: moisturizer presence vs negative mood ----
  const moisturizerIds = new Set(products.filter((p) => p.category === "moisturizer").map((p) => p.id));
  let withMoist = [0, 0], withoutMoist = [0, 0];
  dates.forEach((d) => {
    const l = logs[d];
    if (!l.pmMood) return;
    const hasMoist = Object.keys(l.pm || {}).some((id) => l.pm[id] && moisturizerIds.has(id));
    const negative = NEGATIVE_MOODS.includes(l.pmMood);
    const bucket = hasMoist ? withMoist : withoutMoist;
    bucket[1]++;
    if (negative) bucket[0]++;
  });
  let correlation = null;
  if (withMoist[1] >= 5 && withoutMoist[1] >= 5) {
    const rateWith = withMoist[0] / withMoist[1];
    const rateWithout = withoutMoist[0] / withoutMoist[1];
    if (rateWithout > rateWith + 0.15) {
      correlation = `Nights without a moisturizer checked show more Dry/Irritated logs (${Math.round(rateWithout * 100)}% vs ${Math.round(rateWith * 100)}% with one).`;
    }
  }

  // ---- did the irritation banner actually change behavior? ----
  const exfoliantIds = new Set(products.filter((p) => p.exfoliant).map((p) => p.id));
  let bannerFired = 0, bannerResponded = 0;
  rangeDays.forEach((d) => {
    const last3 = [0, 1, 2].map((i) => { const l = logs[addDays(d, -i)]; return l ? l.pmMood : null; });
    const wouldFire = last3.every((m) => m && NEGATIVE_MOODS.includes(m));
    if (!wouldFire) return;
    const dayBeforeExfoliant = Object.keys(logs[addDays(d, -1)]?.pm || {}).some((id) => logs[addDays(d, -1)].pm[id] && exfoliantIds.has(id));
    const nextDay = addDays(d, 1);
    if (nextDay > todayD) return;
    const nextLog = logs[nextDay];
    if (!nextLog) return;
    bannerFired++;
    const nextExfoliant = Object.keys(nextLog.pm || {}).some((id) => nextLog.pm[id] && exfoliantIds.has(id));
    if (dayBeforeExfoliant && !nextExfoliant) bannerResponded++;
  });
  const bannerInsight = bannerFired >= 3
    ? `The irritation banner has shown ${bannerFired} times — you skipped an active the next night ${Math.round((bannerResponded / bannerFired) * 100)}% of those times.`
    : null;

  // ---- tracked products ----
  const trackedInsights = products.filter((p) => p.tracked).map((p) => {
    let days = 0, c = todayD;
    while (true) {
      const l = logs[c];
      const used = l && ((l.am && l.am[p.id]) || (l.pm && l.pm[p.id]));
      if (used) { days++; c = addDays(c, -1); } else break;
    }
    return { id: p.id, name: p.name, days, isRetinoid: /tretinoin|retinol|adapalene|retinoid/i.test(p.name) };
  });

  // ---- mood shift after starting a tracked product (speculative, gated) ----
  const moodShifts = products.filter((p) => p.tracked).map((p) => {
    const usedDates = dates.filter((d) => (logs[d].am && logs[d].am[p.id]) || (logs[d].pm && logs[d].pm[p.id]));
    if (usedDates.length === 0) return null;
    const startDate = usedDates[0];
    let beforeTotal = 0, beforeNeg = 0, afterTotal = 0, afterNeg = 0;
    for (let i = 1; i <= 14; i++) {
      const d = addDays(startDate, -i);
      const l = logs[d];
      if (l && l.pmMood) { beforeTotal++; if (NEGATIVE_MOODS.includes(l.pmMood)) beforeNeg++; }
    }
    for (let i = 0; i < 14; i++) {
      const d = addDays(startDate, i);
      if (d > todayD) break;
      const l = logs[d];
      if (l && l.pmMood) { afterTotal++; if (NEGATIVE_MOODS.includes(l.pmMood)) afterNeg++; }
    }
    if (beforeTotal < 5 || afterTotal < 5) return null;
    const beforeRate = beforeNeg / beforeTotal;
    const afterRate = afterNeg / afterTotal;
    const diff = afterRate - beforeRate;
    if (Math.abs(diff) < 0.15) return null;
    return { id: p.id, name: p.name, improved: diff < 0, magnitude: Math.round(Math.abs(diff) * 100) };
  }).filter(Boolean);

  // ---- full-year heatmap (only once there's enough history) ----
  const yearStart = `${new Date().getFullYear()}-01-01`;
  const heatmapDays = [];
  for (let c = yearStart; c <= todayD; c = addDays(c, 1)) {
    const l = logs[c];
    const hasAm = l && anyChecked(l.am);
    const hasPm = l && anyChecked(l.pm);
    let status = "none";
    if (hasAm && hasPm) status = "full"; else if (hasAm || hasPm) status = "partial";
    heatmapDays.push({ d: c, status, dow: parseDate(c).getDay() });
  }
  const showHeatmap = rangeDays.length >= 60;
  const heatmapCols = [];
  if (showHeatmap) {
    let col = new Array(7).fill(null);
    heatmapDays.forEach((cell) => {
      if (cell.dow === 0 && col.some((x) => x)) { heatmapCols.push(col); col = new Array(7).fill(null); }
      col[cell.dow] = cell;
    });
    heatmapCols.push(col);
  }

  // ---- ingredient usage history ----
  const stats = usageStats(products, logs);
  const ingredientList = products
    .map((p) => ({ ...p, ...stats[p.id] }))
    .sort((a, b) => b.count - a.count);

  // ---- fading usage: quietly abandoned without being retired ----
  const fading = rangeDays.length >= 28 ? products.filter((p) => p.status !== "retired").map((p) => {
    let prior = 0, recent = 0;
    for (let i = 15; i <= 28; i++) {
      const l = logs[addDays(todayD, -i)];
      if (l && ((l.am && l.am[p.id]) || (l.pm && l.pm[p.id]))) prior++;
    }
    for (let i = 0; i <= 13; i++) {
      const l = logs[addDays(todayD, -i)];
      if (l && ((l.am && l.am[p.id]) || (l.pm && l.pm[p.id]))) recent++;
    }
    return { id: p.id, name: p.name, prior, recent };
  }).filter((f) => f.prior >= 4 && f.recent <= 1) : [];

  // ---- category balance, all-time ----
  const categoryTotals = {};
  CATS.forEach((c) => (categoryTotals[c.id] = 0));
  products.forEach((p) => { categoryTotals[p.category] = (categoryTotals[p.category] || 0) + (stats[p.id]?.count || 0); });
  const categoryGrandTotal = Object.values(categoryTotals).reduce((a, b) => a + b, 0);
  const categoryBalance = CATS.map((c) => ({ ...c, count: categoryTotals[c.id] || 0 }))
    .filter((c) => c.count > 0)
    .sort((a, b) => b.count - a.count);

  // ---- weekly reflections ----
  const weeklyEntries = dates.filter((d) => logs[d].weeklyMood || logs[d].weeklyNote).sort((a, b) => (a < b ? 1 : -1));

  // ---- recent nightly/morning check-ins ----
  const noted = dates
    .filter((d) => (logs[d].amNote && logs[d].amNote.trim()) || (logs[d].pmNote && logs[d].pmNote.trim()) || logs[d].amMood || logs[d].pmMood)
    .sort((a, b) => (a < b ? 1 : -1)).slice(0, 6);

  return (
    <div style={{ padding: "24px 20px 8px" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 4 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <BarChart3 size={16} style={{ color: "var(--amber)" }} />
          <span className="font-mono" style={{ fontSize: 11, letterSpacing: 2, color: "var(--muted)" }}>INSIGHTS</span>
        </div>
        <button onClick={() => setShowExport(true)} style={{ background: "none", border: "1px solid rgba(255,255,255,0.12)", borderRadius: 999, padding: "5px 12px", display: "flex", alignItems: "center", gap: 5, cursor: "pointer" }}>
          <Download size={12} color="var(--muted)" />
          <span style={{ fontSize: 11, color: "var(--muted)" }}>Export</span>
        </button>
      </div>
      <h2 className="font-display" style={{ fontSize: 26, color: "var(--mist)", margin: "4px 0 18px", fontWeight: 500 }}>What the data says</h2>

      {showExport && <ExportSheet onClose={() => setShowExport(false)} onExportJSON={onExport} />}

      {/* top stat row */}
      <div style={{ display: "flex", gap: 10, marginBottom: 10 }}>
        <div className="glass" style={{ flex: 1, borderRadius: 16, padding: 14 }}>
          <div className="font-display" style={{ fontSize: 22, color: "var(--mist)" }}>{consistency}%</div>
          <div style={{ fontSize: 10.5, color: "var(--muted)" }}>this month</div>
        </div>
        <div className="glass" style={{ flex: 1, borderRadius: 16, padding: 14 }}>
          <div className="font-display" style={{ fontSize: 22, color: "var(--mist)" }}>{currentStreak}</div>
          <div style={{ fontSize: 10.5, color: "var(--muted)" }}>current streak</div>
        </div>
        <div className="glass" style={{ flex: 1, borderRadius: 16, padding: 14 }}>
          <div className="font-display" style={{ fontSize: 22, color: "var(--mist)" }}>{longest}</div>
          <div style={{ fontSize: 10.5, color: "var(--muted)" }}>best streak</div>
        </div>
      </div>

      {/* journey summary + month delta */}
      <div style={{ marginBottom: 18 }}>
        <div style={{ fontSize: 11.5, color: "var(--muted)", lineHeight: 1.6 }}>
          Since {prettyDate(firstDate) === "Today" ? "today" : parseDate(firstDate).toLocaleDateString(undefined, { month: "short", day: "numeric" })}:{" "}
          <span style={{ color: "var(--mist)" }}>{dates.length} days tracked</span> · <span style={{ color: "var(--mist)" }}>{totalCheckins} check-ins</span>
          {biggestGap > 1 && <> · longest gap <span style={{ color: "var(--mist)" }}>{biggestGap}d</span></>}
        </div>
        {monthDelta !== null && (
          <div style={{ fontSize: 12.5, color: monthDelta >= 0 ? "var(--amber)" : "var(--muted)", marginTop: 6 }}>
            {monthDelta >= 0 ? "▲" : "▼"} {Math.abs(monthDelta)}% {monthDelta >= 0 ? "more" : "less"} consistent than last month
          </div>
        )}
      </div>

      {/* 6-month trend */}
      <SectionLabel>Consistency, last 6 months</SectionLabel>
      <div className="glass" style={{ borderRadius: 16, padding: "16px 14px", marginBottom: 18 }}>
        <div style={{ display: "flex", alignItems: "flex-end", justifyContent: "space-between", height: 70, gap: 8 }}>
          {monthTrend.map((m, i) => (
            <div key={i} style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", gap: 6 }}>
              <div style={{ width: "100%", height: 54, display: "flex", alignItems: "flex-end" }}>
                <div style={{
                  width: "100%", borderRadius: 4, height: `${Math.max(4, m.pct)}%`,
                  background: m.isCurrent ? "var(--amber)" : "rgba(216,166,87,0.35)",
                }} />
              </div>
              <span className="font-mono" style={{ fontSize: 9, color: m.isCurrent ? "var(--amber)" : "var(--muted)" }}>{m.label}</span>
            </div>
          ))}
        </div>
      </div>

      {/* this month, full vs partial vs missed */}
      {monthTotalDays > 0 && (
        <>
          <SectionLabel>This month, day by day</SectionLabel>
          <div className="glass" style={{ borderRadius: 16, padding: 16, marginBottom: 18 }}>
            <div style={{ display: "flex", height: 10, borderRadius: 5, overflow: "hidden", marginBottom: 10 }}>
              <div style={{ width: `${(fullDays / monthTotalDays) * 100}%`, background: "var(--amber)" }} />
              <div style={{ width: `${(partialDays / monthTotalDays) * 100}%`, background: "rgba(216,166,87,0.4)" }} />
              <div style={{ width: `${(missedDays / monthTotalDays) * 100}%`, background: "rgba(255,255,255,0.08)" }} />
            </div>
            <div style={{ display: "flex", gap: 16 }}>
              <LegendDot color="var(--amber)" label={`${fullDays} full`} />
              <LegendDot color="rgba(216,166,87,0.4)" label={`${partialDays} partial`} />
              <LegendDot color="rgba(255,255,255,0.2)" label={`${missedDays} missed`} />
            </div>
          </div>
        </>
      )}

      {/* full-year heatmap */}
      {showHeatmap && (
        <>
          <SectionLabel>{new Date().getFullYear()}, at a glance</SectionLabel>
          <div className="glass" style={{ borderRadius: 16, padding: 14, marginBottom: 18, overflowX: "auto" }}>
            <div style={{ display: "flex", gap: 2 }}>
              {heatmapCols.map((col, ci) => (
                <div key={ci} style={{ display: "flex", flexDirection: "column", gap: 2 }}>
                  {col.map((cell, ri) => (
                    <div
                      key={ri}
                      style={{
                        width: 8, height: 8, borderRadius: 2,
                        background: !cell ? "transparent" : cell.status === "full" ? "var(--amber)" : cell.status === "partial" ? "rgba(216,166,87,0.4)" : "rgba(255,255,255,0.06)",
                      }}
                    />
                  ))}
                </div>
              ))}
            </div>
          </div>
        </>
      )}

      {/* storage quota */}
      <SectionLabel>Storage</SectionLabel>
      <div className="glass" style={{ borderRadius: 16, padding: 16, marginBottom: 18 }}>
        <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 6 }}>
          <span style={{ fontSize: 12, color: "var(--mist)" }}>Used</span>
          <span className="font-mono" style={{ fontSize: 11.5, color: quotaPct > 85 ? "#e0a87a" : "var(--amber)" }}>
            {quotaUsedMB.toFixed(1)} / {TOTAL_QUOTA_MB} MB
          </span>
        </div>
        <div style={{ height: 6, borderRadius: 3, background: "rgba(255,255,255,0.06)", overflow: "hidden" }}>
          <div style={{ width: `${quotaPct}%`, height: "100%", background: quotaPct > 85 ? "#e0a87a" : "var(--amber)", borderRadius: 3 }} />
        </div>
        {quotaPct > 85 && (
          <div style={{ fontSize: 11, color: "#e0a87a", marginTop: 8 }}>Getting close to the limit — consider cleaning up old photos in Journey.</div>
        )}
      </div>

      {/* photo timeline strip */}
      {photoEntries.length > 0 && (
        <>
          <SectionLabel>Your timeline</SectionLabel>
          <div style={{ display: "flex", gap: 8, overflowX: "auto", paddingBottom: 4, marginBottom: 18 }}>
            {photoEntries.map((e) => (
              <LazyPhoto
                key={`${e.date}:${e.period}:${e.id}`}
                date={e.date}
                period={e.period}
                id={e.id}
                loadPhoto={loadPhoto}
                cached={photoCache[photoKey(e.date, e.period, e.id)]}
                size={56}
                tag={e.period.toUpperCase()}
                onClick={() => setLightbox(e)}
              />
            ))}
          </div>
        </>
      )}

      {/* AM vs PM split */}
      <SectionLabel>Morning vs night</SectionLabel>
      <div className="glass" style={{ borderRadius: 16, padding: 16, marginBottom: 18 }}>
        <SplitBar icon={<Sun size={12} color="var(--amber)" />} label="Morning" pct={amPct} />
        <div style={{ height: 10 }} />
        <SplitBar icon={<Moon size={12} color="var(--amber)" />} label="Night" pct={pmPct} />
      </div>

      {/* category balance */}
      {categoryBalance.length > 0 && (
        <>
          <SectionLabel>Where your steps go</SectionLabel>
          <div className="glass" style={{ borderRadius: 16, padding: 16, marginBottom: 18 }}>
            {categoryBalance.map((c) => {
              const Icon = c.icon;
              const pct = Math.round((c.count / categoryGrandTotal) * 100);
              return (
                <div key={c.id} style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 8 }}>
                  <Icon size={12} style={{ color: "var(--amber)", flexShrink: 0 }} />
                  <span style={{ fontSize: 11.5, color: "var(--muted)", width: 74, flexShrink: 0 }}>{c.label}</span>
                  <div style={{ flex: 1, height: 8, borderRadius: 4, background: "rgba(255,255,255,0.06)", overflow: "hidden" }}>
                    <div style={{ width: `${pct}%`, height: "100%", background: "var(--amber)", borderRadius: 4 }} />
                  </div>
                  <span className="font-mono" style={{ fontSize: 10.5, color: "var(--mist)", width: 30, textAlign: "right" }}>{pct}%</span>
                </div>
              );
            })}
          </div>
        </>
      )}

      {/* mood distribution */}
      {totalMoodLogs > 0 && (
        <>
          <SectionLabel>How skin's felt this month</SectionLabel>
          <div className="glass" style={{ borderRadius: 16, padding: 16, marginBottom: 18 }}>
            {MOODS.map((m) => (
              <div key={m} style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 8 }}>
                <span style={{ fontSize: 11.5, color: "var(--muted)", width: 62, flexShrink: 0 }}>{m}</span>
                <div style={{ flex: 1, height: 8, borderRadius: 4, background: "rgba(255,255,255,0.06)", overflow: "hidden" }}>
                  <div style={{ width: `${(moodCounts[m] / maxMoodCount) * 100}%`, height: "100%", background: NEGATIVE_MOODS.includes(m) ? "rgba(216,166,87,0.5)" : "var(--amber)", borderRadius: 4 }} />
                </div>
                <span className="font-mono" style={{ fontSize: 10.5, color: "var(--mist)", width: 16, textAlign: "right" }}>{moodCounts[m]}</span>
              </div>
            ))}
          </div>
        </>
      )}

      {/* pattern callouts */}
      {(skipPattern || bestDayPattern || correlation || bannerInsight || fading.length > 0) && (
        <>
          <SectionLabel>Patterns worth noticing</SectionLabel>
          <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 18 }}>
            {bestDayPattern && (
              <div style={{ borderRadius: 14, padding: "11px 14px", background: "rgba(216,166,87,0.08)", border: "1px solid rgba(216,166,87,0.2)", display: "flex", gap: 9 }}>
                <Sparkles size={13} style={{ color: "var(--amber)", marginTop: 1, flexShrink: 0 }} />
                <span style={{ fontSize: 12, color: "var(--mist)" }}>{bestDayPattern}</span>
              </div>
            )}
            {skipPattern && (
              <div style={{ borderRadius: 14, padding: "11px 14px", background: "rgba(216,166,87,0.08)", border: "1px solid rgba(216,166,87,0.2)", display: "flex", gap: 9 }}>
                <AlertTriangle size={13} style={{ color: "var(--amber)", marginTop: 1, flexShrink: 0 }} />
                <span style={{ fontSize: 12, color: "var(--mist)" }}>{skipPattern}</span>
              </div>
            )}
            {fading.map((f) => (
              <div key={f.id} style={{ borderRadius: 14, padding: "11px 14px", background: "rgba(216,166,87,0.08)", border: "1px solid rgba(216,166,87,0.2)", display: "flex", gap: 9 }}>
                <Archive size={13} style={{ color: "var(--amber)", marginTop: 1, flexShrink: 0 }} />
                <span style={{ fontSize: 12, color: "var(--mist)", lineHeight: 1.5 }}>
                  Barely touched lately: <span style={{ color: "var(--amber)" }}>{f.name}</span> — {f.prior}× two weeks ago, just {f.recent}× since. Worth retiring?
                </span>
              </div>
            ))}
            {correlation && (
              <div style={{ borderRadius: 14, padding: "11px 14px", background: "rgba(216,166,87,0.08)", border: "1px solid rgba(216,166,87,0.2)", display: "flex", gap: 9 }}>
                <Sparkles size={13} style={{ color: "var(--amber)", marginTop: 1, flexShrink: 0 }} />
                <span style={{ fontSize: 12, color: "var(--mist)", lineHeight: 1.5 }}>{correlation}</span>
              </div>
            )}
            {bannerInsight && (
              <div style={{ borderRadius: 14, padding: "11px 14px", background: "rgba(216,166,87,0.08)", border: "1px solid rgba(216,166,87,0.2)", display: "flex", gap: 9 }}>
                <AlertTriangle size={13} style={{ color: "var(--amber)", marginTop: 1, flexShrink: 0 }} />
                <span style={{ fontSize: 12, color: "var(--mist)", lineHeight: 1.5 }}>{bannerInsight}</span>
              </div>
            )}
          </div>
        </>
      )}

      {/* tracked products */}
      {trackedInsights.length > 0 && (
        <>
          <SectionLabel>Tracked products</SectionLabel>
          <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 18 }}>
            {trackedInsights.map((t) => (
              <div key={t.id} className="glass" style={{ borderRadius: 14, padding: 13 }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline" }}>
                  <span style={{ fontSize: 13, color: "var(--mist)" }}>{t.name}</span>
                  <span className="font-mono" style={{ fontSize: 13, color: "var(--amber)" }}>Day {t.days}</span>
                </div>
                {t.isRetinoid && (
                  <div style={{ fontSize: 11, color: "var(--muted)", marginTop: 4 }}>
                    Most retinoid adjustment periods ease by week 4–6.
                  </div>
                )}
              </div>
            ))}
          </div>
        </>
      )}

      {/* mood shift after starting a tracked product — speculative, clearly caveated */}
      {moodShifts.length > 0 && (
        <>
          <SectionLabel>Since starting these</SectionLabel>
          <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 18 }}>
            {moodShifts.map((m) => (
              <div key={m.id} style={{ borderRadius: 14, padding: "11px 14px", background: "rgba(216,166,87,0.06)", border: "1px solid rgba(216,166,87,0.15)" }}>
                <div style={{ fontSize: 12, color: "var(--mist)" }}>
                  {m.improved ? "Fewer" : "More"} negative mood logs since starting <span style={{ color: "var(--amber)" }}>{m.name}</span> ({m.magnitude}% shift)
                </div>
                <div style={{ fontSize: 10.5, color: "var(--muted)", marginTop: 4 }}>
                  May be related, not proof — plenty else could explain it.
                </div>
              </div>
            ))}
          </div>
        </>
      )}

      {/* ingredient history */}
      <SectionLabel>Ingredient history</SectionLabel>
      <div className="glass" style={{ borderRadius: 16, padding: 6, marginBottom: 18 }}>
        {ingredientList.map((s, i) => (
          <div
            key={s.id}
            onClick={() => s.count > 0 && setHistoryProduct(s.id)}
            style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "10px 10px", borderBottom: i < ingredientList.length - 1 ? "1px solid rgba(255,255,255,0.05)" : "none", cursor: s.count > 0 ? "pointer" : "default" }}
          >
            <div>
              <div style={{ fontSize: 13, color: "var(--mist)" }}>{s.name}</div>
              <div className="font-mono" style={{ fontSize: 10.5, color: "var(--muted)", marginTop: 2 }}>{s.last ? `last used ${prettyDate(s.last)}` : "not used yet"}</div>
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
              <span className="font-mono" style={{ fontSize: 13, color: "var(--amber)" }}>{s.count}d</span>
              {s.count > 0 && <ChevronRight size={14} color="var(--muted)" />}
            </div>
          </div>
        ))}
      </div>

      {historyProduct && (
        <ProductHistoryModal
          product={products.find((p) => p.id === historyProduct)}
          logs={logs}
          onClose={() => setHistoryProduct(null)}
        />
      )}

      {/* weekly reflections */}
      {weeklyEntries.length > 0 && (
        <>
          <SectionLabel>Weekly reflections</SectionLabel>
          <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 18 }}>
            {weeklyEntries.slice(0, 5).map((d) => (
              <div key={d} className="glass" style={{ borderRadius: 14, padding: 12 }}>
                <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 4 }}>
                  <span className="font-mono" style={{ fontSize: 10.5, color: "var(--muted)" }}>{prettyDate(d)}</span>
                  {logs[d].weeklyMood && <span className="font-mono" style={{ fontSize: 10.5, color: "var(--amber)" }}>{logs[d].weeklyMood}</span>}
                </div>
                {logs[d].weeklyNote && <div style={{ fontSize: 12.5, color: "var(--mist)" }}>{logs[d].weeklyNote}</div>}
              </div>
            ))}
          </div>
        </>
      )}

      {/* recent check-ins */}
      {noted.length > 0 && (
        <>
          <SectionLabel>Recent check-ins</SectionLabel>
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {noted.map((d) => (
              <div key={d} className="glass" style={{ borderRadius: 14, padding: 12 }}>
                <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 4 }}>
                  <span className="font-mono" style={{ fontSize: 10.5, color: "var(--muted)" }}>{prettyDate(d)}</span>
                  {(logs[d].amMood || logs[d].pmMood) && (
                    <span className="font-mono" style={{ fontSize: 10.5, color: "var(--amber)" }}>
                      {[logs[d].amMood, logs[d].pmMood].filter(Boolean).join(" · ")}
                    </span>
                  )}
                </div>
                {logs[d].amNote && <div style={{ fontSize: 12.5, color: "var(--mist)" }}>AM — {logs[d].amNote}</div>}
                {logs[d].pmNote && <div style={{ fontSize: 12.5, color: "var(--mist)", marginTop: 2 }}>PM — {logs[d].pmNote}</div>}
              </div>
            ))}
          </div>
        </>
      )}

      {lightbox && (
        <div
          style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.85)", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", zIndex: 60, padding: 24 }}
          onClick={() => setLightbox(null)}
        >
          {photoCache[photoKey(lightbox.date, lightbox.period, lightbox.id)] ? (
            <img src={photoCache[photoKey(lightbox.date, lightbox.period, lightbox.id)]} alt="" style={{ maxWidth: "100%", maxHeight: "70vh", borderRadius: 16 }} onClick={(e) => e.stopPropagation()} />
          ) : (
            <Loader2 className="animate-spin" size={24} color="var(--amber)" />
          )}
          <span className="font-mono" style={{ color: "var(--mist)", fontSize: 13, marginTop: 16 }}>{prettyDate(lightbox.date)} {lightbox.period.toUpperCase()}</span>
        </div>
      )}
    </div>
  );
}

function LegendDot({ color, label }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 5 }}>
      <div style={{ width: 8, height: 8, borderRadius: 3, background: color }} />
      <span style={{ fontSize: 10.5, color: "var(--muted)" }}>{label}</span>
    </div>
  );
}

function buildProductMonthGrid(logs, productId, year, month) {
  const first = new Date(year, month, 1);
  const startOffset = first.getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const cells = [];
  for (let i = 0; i < startOffset; i++) cells.push(null);
  for (let d = 1; d <= daysInMonth; d++) {
    const ds = fmtDate(new Date(year, month, d));
    const l = logs[ds];
    const usedAm = l && l.am && l.am[productId];
    const usedPm = l && l.pm && l.pm[productId];
    let status = "none";
    if (usedAm && usedPm) status = "both"; else if (usedAm) status = "am"; else if (usedPm) status = "pm";
    if (ds > todayStr()) status = "future";
    cells.push({ ds, day: d, status });
  }
  return cells;
}

function ProductHistoryModal({ product, logs, onClose }) {
  const [monthOffset, setMonthOffset] = useState(0);
  if (!product) return null;

  const dates = Object.keys(logs).sort();
  const usedDates = dates.filter((d) => (logs[d].am && logs[d].am[product.id]) || (logs[d].pm && logs[d].pm[product.id]));
  const count = usedDates.length;
  const first = usedDates[0];
  const last = usedDates[usedDates.length - 1];

  const base = new Date();
  base.setMonth(base.getMonth() + monthOffset);
  const year = base.getFullYear(), month = base.getMonth();
  const cells = buildProductMonthGrid(logs, product.id, year, month);
  const monthLabel = base.toLocaleDateString(undefined, { month: "long", year: "numeric" });

  function cellColor(status) {
    if (status === "both") return "var(--amber)";
    if (status === "am" || status === "pm") return "rgba(216,166,87,0.4)";
    return "rgba(255,255,255,0.06)";
  }

  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.6)", display: "flex", alignItems: "flex-end", justifyContent: "center", zIndex: 55 }} onClick={onClose}>
      <div className="glass" onClick={(e) => e.stopPropagation()} style={{ width: "100%", maxWidth: 480, maxHeight: "85vh", overflowY: "auto", borderRadius: "24px 24px 0 0", padding: 20, background: "#141210" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 4 }}>
          <span className="font-display" style={{ fontSize: 18, color: "var(--mist)" }}>{product.name}</span>
          <button onClick={onClose} style={{ background: "none", border: "none", cursor: "pointer" }}><X size={18} color="var(--muted)" /></button>
        </div>
        <div className="font-mono" style={{ fontSize: 11, color: "var(--muted)", marginBottom: 18 }}>
          used {count} days · first {prettyDate(first)} · last {prettyDate(last)}
        </div>

        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 14 }}>
          <button onClick={() => setMonthOffset((o) => o - 1)} style={iconBtnStyle}><ChevronLeft size={14} color="var(--muted)" /></button>
          <span className="font-mono" style={{ fontSize: 12, color: "var(--mist)" }}>{monthLabel}</span>
          <button onClick={() => setMonthOffset((o) => o + 1)} disabled={monthOffset >= 0} style={{ ...iconBtnStyle, opacity: monthOffset >= 0 ? 0.25 : 1 }}><ChevronRight size={14} color="var(--muted)" /></button>
        </div>

        <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", gap: 6, marginBottom: 14 }}>
          {["S", "M", "T", "W", "T", "F", "S"].map((d, i) => (
            <div key={i} className="font-mono" style={{ textAlign: "center", fontSize: 9.5, color: "var(--muted)" }}>{d}</div>
          ))}
          {cells.map((c, i) =>
            c ? (
              <div key={i} style={{
                aspectRatio: "1", borderRadius: 8, display: "flex", alignItems: "center", justifyContent: "center",
                background: c.status === "future" ? "transparent" : cellColor(c.status),
              }}>
                <span className="font-mono" style={{ fontSize: 10.5, color: c.status === "both" ? "#0B0A08" : c.status === "future" ? "rgba(255,255,255,0.15)" : "var(--mist)" }}>
                  {c.day}
                </span>
              </div>
            ) : <div key={i} />
          )}
        </div>

        <div style={{ display: "flex", gap: 14, justifyContent: "center" }}>
          <LegendDot color="var(--amber)" label="AM + PM" />
          <LegendDot color="rgba(216,166,87,0.4)" label="One dose" />
          <LegendDot color="rgba(255,255,255,0.15)" label="Not used" />
        </div>
      </div>
    </div>
  );
}

function ExportSheet({ onClose, onExportJSON }) {
  const [done, setDone] = useState(false);
  function handleExport() {
    onExportJSON();
    setDone(true);
    setTimeout(() => setDone(false), 2000);
  }
  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.6)", display: "flex", alignItems: "flex-end", justifyContent: "center", zIndex: 55 }} onClick={onClose}>
      <div className="glass" onClick={(e) => e.stopPropagation()} style={{ width: "100%", maxWidth: 480, borderRadius: "24px 24px 0 0", padding: 20, background: "#141210" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
          <span className="font-display" style={{ fontSize: 18, color: "var(--mist)" }}>Export your data</span>
          <button onClick={onClose} style={{ background: "none", border: "none", cursor: "pointer" }}><X size={18} color="var(--muted)" /></button>
        </div>

        <button
          onClick={handleExport}
          className="glass"
          style={{ width: "100%", borderRadius: 14, padding: "14px 16px", marginBottom: 10, display: "flex", alignItems: "center", gap: 12, cursor: "pointer", textAlign: "left" }}
        >
          <Download size={18} color="var(--amber)" style={{ flexShrink: 0 }} />
          <div>
            <div style={{ fontSize: 13.5, color: "var(--mist)", fontWeight: 500 }}>{done ? "Downloaded ✓" : "Export data (JSON)"}</div>
            <div style={{ fontSize: 11, color: "var(--muted)", marginTop: 2, lineHeight: 1.5 }}>
              Every product, every logged day, moods, notes, and computed stats — paste it into Claude or ChatGPT and ask anything.
            </div>
          </div>
        </button>

        <div style={{ width: "100%", borderRadius: 14, padding: "14px 16px", display: "flex", alignItems: "center", gap: 12, opacity: 0.45 }}>
          <ImageIcon size={18} color="var(--muted)" style={{ flexShrink: 0 }} />
          <div>
            <div style={{ fontSize: 13.5, color: "var(--mist)", fontWeight: 500 }}>Export photos</div>
            <div style={{ fontSize: 11, color: "var(--muted)", marginTop: 2, lineHeight: 1.5 }}>
              Coming with the standalone website version.
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

