/* -------------------------------- journey view -------------------------------- */

function YearOverview({ year, logs, photoIndex, selectedDate, onPickDay }) {
  const months = Array.from({ length: 12 }, (_, m) => m);
  function statusColor(status) {
    if (status === "full") return "var(--amber)";
    if (status === "partial") return "rgba(216,166,87,0.4)";
    return "rgba(255,255,255,0.06)";
  }
  return (
    <div style={{ maxHeight: 380, overflowY: "auto", display: "flex", flexDirection: "column", gap: 16, paddingTop: 4 }}>
      {months.map((m) => {
        const cells = buildMonthGrid(logs, year, m, photoIndex);
        const label = new Date(year, m, 1).toLocaleDateString(undefined, { month: "short" });
        return (
          <div key={m}>
            <div className="font-mono" style={{ fontSize: 10, color: "var(--muted)", marginBottom: 6 }}>{label}</div>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", gap: 3 }}>
              {cells.map((c, i) =>
                c ? (
                  <div
                    key={i}
                    onClick={() => c.status !== "future" && onPickDay(c.ds)}
                    style={{
                      aspectRatio: "1", borderRadius: 3,
                      background: c.status === "future" ? "transparent" : statusColor(c.status),
                      border: c.ds === selectedDate ? "1px solid var(--mist)" : "none",
                      cursor: c.status === "future" ? "default" : "pointer",
                    }}
                  />
                ) : <div key={i} />
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}

function buildMonthGrid(logs, year, month, photoIndex = {}) {
  const first = new Date(year, month, 1);
  const startOffset = first.getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const cells = [];
  for (let i = 0; i < startOffset; i++) cells.push(null);
  for (let d = 1; d <= daysInMonth; d++) {
    const ds = fmtDate(new Date(year, month, d));
    const l = logs[ds];
    const hasAm = l && Object.values(l.am || {}).some(Boolean);
    const hasPm = l && Object.values(l.pm || {}).some(Boolean);
    let status = "none";
    if (hasAm && hasPm) status = "full";
    else if (hasAm || hasPm) status = "partial";
    if (ds > todayStr()) status = "future";
    const ph = photoIndex[ds];
    const hasPhoto = !!(ph && ((ph.am && ph.am.length) || (ph.pm && ph.pm.length)));
    cells.push({ ds, day: d, status, hasPhoto });
  }
  return cells;
}

function JourneyView({ products, logs, selectedDate, setSelectedDate, setTab, photoIndex, photoCache, loadPhoto, onTriggerPhoto, onDelete, onDeleteMany, photoError, quotaUsedMB, quotaPct }) {
  const [monthOffset, setMonthOffset] = useState(0);
  const [calView, setCalView] = useState("month"); // 'month' | 'year'
  const [previewDate, setPreviewDate] = useState(null);
  const [mode, setMode] = useState("grid");
  const [viewing, setViewing] = useState(null); // {date, period, id} | null
  const [selectMode, setSelectMode] = useState(false);
  const [selected, setSelected] = useState(new Set());
  const [compareA, setCompareA] = useState(null); // {date, period, id} | null
  const [compareB, setCompareB] = useState(null);
  const [picking, setPicking] = useState(null); // 'A' | 'B' | null

  const base = new Date();
  base.setMonth(base.getMonth() + monthOffset);
  const year = base.getFullYear(), month = base.getMonth();
  const cells = useMemo(() => buildMonthGrid(logs, year, month, photoIndex), [logs, year, month, photoIndex]);
  const monthLabel = base.toLocaleDateString(undefined, { month: "long", year: "numeric" });

  // flattened photo entries, newest first
  const entries = useMemo(() => {
    const list = [];
    Object.keys(photoIndex).forEach((d) => {
      const slot = photoIndex[d];
      (slot.am || []).forEach((id) => list.push({ date: d, period: "am", id }));
      (slot.pm || []).forEach((id) => list.push({ date: d, period: "pm", id }));
    });
    return list.sort((a, b) => (a.date === b.date ? (a.period === b.period ? 0 : a.period < b.period ? -1 : 1) : a.date < b.date ? 1 : -1));
  }, [photoIndex]);

  function entryKey(e) { return `${e.date}:${e.period}:${e.id}`; }
  function entryLabel(e) { return `${prettyDate(e.date)} ${e.period.toUpperCase()}`; }
  function sameEntry(a, b) { return a && b && a.date === b.date && a.period === b.period && a.id === b.id; }

  function statusColor(status) {
    if (status === "full") return "var(--amber)";
    if (status === "partial") return "rgba(216,166,87,0.4)";
    return "rgba(255,255,255,0.06)";
  }

  function toggleSelected(k) {
    setSelected((s) => {
      const next = new Set(s);
      if (next.has(k)) next.delete(k); else next.add(k);
      return next;
    });
  }

  async function deleteSelected() {
    const list = entries.filter((e) => selected.has(entryKey(e)));
    await onDeleteMany(list);
    setSelected(new Set());
    setSelectMode(false);
  }

  async function deleteOlderThan90() {
    const cutoff = addDays(todayStr(), -90);
    const list = entries.filter((e) => e.date < cutoff);
    if (list.length === 0) return;
    await onDeleteMany(list);
  }

  function applyQuickCompare(daysAgo) {
    if (entries.length === 0) return;
    const after = entries[0]; // most recent
    const target = addDays(after.date, -daysAgo);
    let closest = entries[0];
    let closestDiff = Infinity;
    entries.forEach((e) => {
      const diff = Math.abs(parseDate(e.date) - parseDate(target));
      if (diff < closestDiff) { closestDiff = diff; closest = e; }
    });
    setCompareB(after);
    setCompareA(closest);
  }

  const elapsedDays = compareA && compareB ? Math.round(Math.abs(parseDate(compareB.date) - parseDate(compareA.date)) / 86400000) : null;

  const previewLog = previewDate ? logs[previewDate] : null;
  const previewAmCount = previewLog ? Object.values(previewLog.am || {}).filter(Boolean).length : 0;
  const previewPmCount = previewLog ? Object.values(previewLog.pm || {}).filter(Boolean).length : 0;
  const previewPhotos = previewDate ? entries.filter((e) => e.date === previewDate) : [];

  return (
    <div style={{ padding: "24px 20px 8px" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
        <Circle size={16} style={{ color: "var(--amber)" }} />
        <span className="font-mono" style={{ fontSize: 11, letterSpacing: 2, color: "var(--muted)" }}>JOURNEY</span>
      </div>
      <h2 className="font-display" style={{ fontSize: 26, color: "var(--mist)", margin: "4px 0 16px", fontWeight: 500 }}>Your progress, over time</h2>

      {/* storage quota */}
      <div style={{ marginBottom: 18 }}>
        <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 5 }}>
          <span style={{ fontSize: 11, color: "var(--muted)" }}>Storage used</span>
          <span className="font-mono" style={{ fontSize: 11, color: quotaPct > 85 ? "#e0a87a" : "var(--muted)" }}>
            {quotaUsedMB.toFixed(1)} / {TOTAL_QUOTA_MB} MB
          </span>
        </div>
        <div style={{ height: 5, borderRadius: 3, background: "rgba(255,255,255,0.06)", overflow: "hidden" }}>
          <div style={{ width: `${quotaPct}%`, height: "100%", background: quotaPct > 85 ? "#e0a87a" : "var(--amber)", borderRadius: 3 }} />
        </div>
      </div>

      {photoError && (
        <div style={{ borderRadius: 12, padding: "9px 12px", marginBottom: 14, background: "rgba(224,138,122,0.1)", border: "1px solid rgba(224,138,122,0.3)" }}>
          <span style={{ fontSize: 12, color: "#e0a87a" }}>{photoError}</span>
        </div>
      )}

      {/* calendar */}
      <div className="glass" style={{ borderRadius: 18, padding: 16, marginBottom: 20 }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 14, position: "relative" }}>
          {calView === "month" ? (
            <>
              <button onClick={() => setMonthOffset((o) => o - 1)} style={iconBtnStyle}><ChevronLeft size={14} color="var(--muted)" /></button>
              <span className="font-mono" style={{ fontSize: 12, color: "var(--mist)" }}>{monthLabel}</span>
              <button onClick={() => setMonthOffset((o) => o + 1)} disabled={monthOffset >= 0} style={{ ...iconBtnStyle, opacity: monthOffset >= 0 ? 0.25 : 1 }}><ChevronRight size={14} color="var(--muted)" /></button>
            </>
          ) : (
            <span className="font-mono" style={{ fontSize: 12, color: "var(--mist)" }}>{year}</span>
          )}
          <button
            onClick={() => setCalView((v) => (v === "month" ? "year" : "month"))}
            style={{ position: "absolute", right: 36, background: "none", border: "1px solid rgba(255,255,255,0.12)", borderRadius: 999, padding: "3px 10px", fontSize: 10.5, color: "var(--muted)", cursor: "pointer" }}
          >
            {calView === "month" ? "Year" : "Month"}
          </button>
        </div>

        {calView === "month" ? (
          <>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", gap: 6 }}>
              {["S", "M", "T", "W", "T", "F", "S"].map((d, i) => (
                <div key={i} className="font-mono" style={{ textAlign: "center", fontSize: 9.5, color: "var(--muted)" }}>{d}</div>
              ))}
              {cells.map((c, i) =>
                c ? (
                  <div
                    key={i}
                    onClick={() => { if (c.status === "future") return; setSelectedDate(c.ds); setPreviewDate(c.ds); }}
                    style={{
                      position: "relative", aspectRatio: "1", borderRadius: 8, display: "flex", alignItems: "center", justifyContent: "center",
                      background: c.status === "future" ? "transparent" : statusColor(c.status),
                      border: c.ds === selectedDate ? "1.5px solid var(--mist)" : "1px solid transparent",
                      cursor: c.status === "future" ? "default" : "pointer",
                    }}
                  >
                    <span className="font-mono" style={{ fontSize: 10.5, color: c.status === "full" ? "#0B0A08" : c.status === "future" ? "rgba(255,255,255,0.15)" : "var(--mist)" }}>
                      {c.day}
                    </span>
                    {c.hasPhoto && (
                      <div style={{ position: "absolute", bottom: 2, width: 3, height: 3, borderRadius: "50%", background: c.status === "full" ? "#0B0A08" : "var(--amber)" }} />
                    )}
                  </div>
                ) : <div key={i} />
              )}
            </div>
            <div style={{ display: "flex", gap: 14, marginTop: 14, justifyContent: "center", flexWrap: "wrap" }}>
              {[["full", "Full"], ["partial", "Partial"], ["none", "Missed"]].map(([k, label]) => (
                <LegendDot key={k} color={statusColor(k)} label={label} />
              ))}
              <div style={{ display: "flex", alignItems: "center", gap: 5 }}>
                <div style={{ width: 3, height: 3, borderRadius: "50%", background: "var(--amber)" }} />
                <span style={{ fontSize: 10.5, color: "var(--muted)" }}>Photo</span>
              </div>
            </div>
          </>
        ) : (
          <YearOverview year={year} logs={logs} photoIndex={photoIndex} selectedDate={selectedDate} onPickDay={(ds) => { setSelectedDate(ds); setPreviewDate(ds); }} />
        )}
      </div>

      {/* day preview */}
      {previewDate && (
        <div className="glass" style={{ borderRadius: 16, padding: 16, marginBottom: 20 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 10 }}>
            <span className="font-display" style={{ fontSize: 16, color: "var(--mist)" }}>{prettyDate(previewDate)}</span>
            <button onClick={() => setPreviewDate(null)} style={{ background: "none", border: "none", cursor: "pointer" }}><X size={16} color="var(--muted)" /></button>
          </div>
          <div style={{ display: "flex", gap: 16, marginBottom: previewPhotos.length ? 12 : 0 }}>
            <span className="font-mono" style={{ fontSize: 11, color: "var(--muted)" }}>AM {previewAmCount} checked</span>
            <span className="font-mono" style={{ fontSize: 11, color: "var(--muted)" }}>PM {previewPmCount} checked</span>
            {(previewLog?.amMood || previewLog?.pmMood) && (
              <span className="font-mono" style={{ fontSize: 11, color: "var(--amber)" }}>
                {[previewLog.amMood, previewLog.pmMood].filter(Boolean).join(" · ")}
              </span>
            )}
          </div>
          {previewPhotos.length > 0 && (
            <div style={{ display: "flex", gap: 8, marginBottom: 12, flexWrap: "wrap" }}>
              {previewPhotos.map((p) => (
                <LazyPhoto key={entryKey(p)} date={p.date} period={p.period} id={p.id} loadPhoto={loadPhoto} cached={photoCache[photoKey(p.date, p.period, p.id)]} size={52} tag={p.period.toUpperCase()} onClick={() => setViewing(p)} />
              ))}
            </div>
          )}
          <button
            onClick={() => setTab("today")}
            style={{ background: "none", border: "none", padding: 0, cursor: "pointer", display: "flex", alignItems: "center", gap: 4, color: "var(--amber)", fontSize: 12.5 }}
          >
            View full day <ArrowRight size={12} />
          </button>
        </div>
      )}

      {/* add photo */}
      <div style={{ display: "flex", gap: 8, marginBottom: 6 }}>
        <button onClick={() => onTriggerPhoto("am")} className="glass" style={{ flex: 1, borderRadius: 14, padding: "11px 0", display: "flex", alignItems: "center", justifyContent: "center", gap: 6, color: "var(--amber)", fontSize: 12.5, fontWeight: 500, cursor: "pointer" }}>
          <Sun size={13} /> Add AM photo
        </button>
        <button onClick={() => onTriggerPhoto("pm")} className="glass" style={{ flex: 1, borderRadius: 14, padding: "11px 0", display: "flex", alignItems: "center", justifyContent: "center", gap: 6, color: "var(--amber)", fontSize: 12.5, fontWeight: 500, cursor: "pointer" }}>
          <Moon size={13} /> Add PM photo
        </button>
      </div>
      <div className="font-mono" style={{ fontSize: 10, color: "var(--muted)", marginBottom: 16 }}>
        for {prettyDate(selectedDate).toLowerCase()} — front, side, whatever angle. Add as many as you want.
      </div>

      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 12 }}>
        <span style={{ fontSize: 11, color: "var(--muted)", letterSpacing: 1, textTransform: "uppercase" }}>Timeline</span>
        <div style={{ display: "flex", gap: 6 }}>
          {["grid", "compare"].map((m) => (
            <button key={m} onClick={() => { setMode(m); setSelectMode(false); }} style={{ padding: "5px 12px", borderRadius: 999, fontSize: 11.5, cursor: "pointer", border: `1px solid ${mode === m ? "var(--amber)" : "rgba(255,255,255,0.1)"}`, background: mode === m ? "var(--amber-dim)" : "transparent", color: mode === m ? "var(--amber)" : "var(--muted)" }}>
              {m === "grid" ? "Gallery" : "Compare"}
            </button>
          ))}
        </div>
      </div>

      {mode === "grid" && (
        <>
          {entries.length === 0 && <div style={{ textAlign: "center", color: "var(--muted)", fontSize: 13, marginTop: 24, marginBottom: 20 }}>No photos yet.</div>}

          {entries.length > 0 && (
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
              <button onClick={() => { setSelectMode((v) => !v); setSelected(new Set()); }} style={{ background: "none", border: "none", cursor: "pointer", fontSize: 11.5, color: selectMode ? "var(--amber)" : "var(--muted)" }}>
                {selectMode ? "Cancel" : "Select"}
              </button>
              {!selectMode && (
                <button onClick={deleteOlderThan90} style={{ background: "none", border: "none", cursor: "pointer", fontSize: 11.5, color: "var(--muted)" }}>
                  Clean up 90+ days
                </button>
              )}
            </div>
          )}

          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 8, marginBottom: 10 }}>
            {entries.map((e) => {
              const k = entryKey(e);
              return (
                <LazyPhoto
                  key={k}
                  date={e.date}
                  period={e.period}
                  id={e.id}
                  loadPhoto={loadPhoto}
                  cached={photoCache[photoKey(e.date, e.period, e.id)]}
                  size="100%"
                  radius={12}
                  tag={`${e.date.slice(5)} ${e.period.toUpperCase()}`}
                  selected={selectMode && selected.has(k)}
                  onClick={() => (selectMode ? toggleSelected(k) : setViewing(e))}
                />
              );
            })}
          </div>

          {selectMode && selected.size > 0 && (
            <button onClick={deleteSelected} style={{ width: "100%", padding: "11px 0", borderRadius: 12, border: "1px solid rgba(224,138,122,0.35)", background: "transparent", color: "#e0a87a", fontSize: 13, cursor: "pointer", marginTop: 4 }}>
              Delete {selected.size} photo{selected.size > 1 ? "s" : ""}
            </button>
          )}
        </>
      )}

      {mode === "compare" && (
        <div style={{ marginBottom: 20 }}>
          {entries.length === 0 ? (
            <div style={{ textAlign: "center", color: "var(--muted)", fontSize: 13, marginTop: 24, marginBottom: 20 }}>No photos yet to compare.</div>
          ) : (
            <>
              <div style={{ display: "flex", gap: 6, marginBottom: 12 }}>
                <button onClick={() => applyQuickCompare(30)} style={quickBtnStyle}>vs 30d ago</button>
                <button onClick={() => applyQuickCompare(90)} style={quickBtnStyle}>vs 90d ago</button>
              </div>
              {elapsedDays !== null && (
                <div className="font-mono" style={{ fontSize: 11, color: "var(--amber)", textAlign: "center", marginBottom: 10 }}>{elapsedDays} days apart</div>
              )}
              <div style={{ display: "flex", gap: 8 }}>
                {[["Before", compareA, setCompareA, "A"], ["After", compareB, setCompareB, "B"]].map(([label, val, setter, slot]) => (
                  <div key={slot} style={{ flex: 1 }}>
                    <div
                      onClick={() => setPicking(slot)}
                      style={{
                        aspectRatio: "0.85", borderRadius: 14, overflow: "hidden", background: "rgba(255,255,255,0.04)",
                        border: "1px solid rgba(255,255,255,0.08)", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", position: "relative",
                      }}
                    >
                      {val ? (
                        <img src={photoCache[photoKey(val.date, val.period, val.id)]} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                      ) : (
                        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 6 }}>
                          <ImageIcon size={18} color="var(--muted)" />
                          <span style={{ fontSize: 10.5, color: "var(--muted)" }}>Choose {label.toLowerCase()}</span>
                        </div>
                      )}
                    </div>
                    {val && (
                      <div className="font-mono" style={{ fontSize: 9.5, color: "var(--muted)", textAlign: "center", marginTop: 5 }}>{entryLabel(val)}</div>
                    )}
                  </div>
                ))}
              </div>
            </>
          )}
        </div>
      )}

      {picking && (
        <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.6)", display: "flex", alignItems: "flex-end", justifyContent: "center", zIndex: 55 }} onClick={() => setPicking(null)}>
          <div className="glass" onClick={(e) => e.stopPropagation()} style={{ width: "100%", maxWidth: 480, maxHeight: "75vh", overflowY: "auto", borderRadius: "24px 24px 0 0", padding: 20, background: "#141210" }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
              <span className="font-display" style={{ fontSize: 18, color: "var(--mist)" }}>Choose a photo</span>
              <button onClick={() => setPicking(null)} style={{ background: "none", border: "none", cursor: "pointer" }}><X size={18} color="var(--muted)" /></button>
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 8 }}>
              {entries.map((e) => (
                <LazyPhoto
                  key={entryKey(e)}
                  date={e.date}
                  period={e.period}
                  id={e.id}
                  loadPhoto={loadPhoto}
                  cached={photoCache[photoKey(e.date, e.period, e.id)]}
                  size="100%"
                  radius={12}
                  tag={`${e.date.slice(5)} ${e.period.toUpperCase()}`}
                  selected={sameEntry(e, picking === "A" ? compareA : compareB)}
                  onClick={() => { if (picking === "A") setCompareA(e); else setCompareB(e); setPicking(null); }}
                />
              ))}
            </div>
          </div>
        </div>
      )}

      {viewing && (
        <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.85)", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", zIndex: 60, padding: 24 }} onClick={() => setViewing(null)}>
          {photoCache[photoKey(viewing.date, viewing.period, viewing.id)] ? (
            <img src={photoCache[photoKey(viewing.date, viewing.period, viewing.id)]} alt="" style={{ maxWidth: "100%", maxHeight: "70vh", borderRadius: 16 }} onClick={(e) => e.stopPropagation()} />
          ) : (
            <Loader2 className="animate-spin" size={24} color="var(--amber)" />
          )}
          <div style={{ display: "flex", alignItems: "center", gap: 16, marginTop: 16 }}>
            <span className="font-mono" style={{ color: "var(--mist)", fontSize: 13 }}>{entryLabel(viewing)}</span>
            <button
              onClick={(e) => { e.stopPropagation(); onDelete(viewing.date, viewing.period, viewing.id); setViewing(null); }}
              style={{ background: "rgba(255,255,255,0.08)", border: "none", borderRadius: 8, padding: "6px 10px", display: "flex", alignItems: "center", gap: 6, color: "#e0a87a", cursor: "pointer", fontSize: 12 }}
            >
              <Trash2 size={13} /> Delete
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

const quickBtnStyle = {
  padding: "6px 13px", borderRadius: 999, fontSize: 11.5, cursor: "pointer",
  border: "1px solid rgba(255,255,255,0.12)", background: "transparent", color: "var(--muted)",
};

const selectStyle = {
  flex: 1, background: "rgba(255,255,255,0.05)", border: "1px solid rgba(255,255,255,0.1)",
  borderRadius: 10, padding: "9px 10px", color: "var(--mist)", fontSize: 12.5,
};

/* --------------------------------- tab bar --------------------------------- */

function TabBar({ tab, setTab }) {
  const items = [
    { id: "today", icon: Sun, label: "Today" },
    { id: "shelf", icon: Package, label: "Shelf" },
    { id: "insights", icon: BarChart3, label: "Insights" },
    { id: "journey", icon: Circle, label: "Journey" },
  ];
  return (
    <div style={{ position: "fixed", bottom: 0, left: "50%", transform: "translateX(-50%)", width: "100%", maxWidth: 480, padding: "10px 16px calc(10px + env(safe-area-inset-bottom))" }}>
      <div className="glass" style={{ borderRadius: 20, padding: 8, display: "flex", justifyContent: "space-around", background: "rgba(11,10,8,0.9)" }}>
        {items.map((it) => {
          const Icon = it.icon;
          const active = tab === it.id;
          return (
            <button key={it.id} onClick={() => setTab(it.id)} style={{ background: "none", border: "none", cursor: "pointer", display: "flex", flexDirection: "column", alignItems: "center", gap: 4, padding: "6px 12px", borderRadius: 12, color: active ? "var(--amber)" : "var(--muted)" }}>
              <Icon size={18} strokeWidth={active ? 2.3 : 1.8} />
              <span className="font-mono" style={{ fontSize: 9.5, letterSpacing: 0.5 }}>{it.label.toUpperCase()}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
}
